def main():
    heroes_path = os.path.join(DATA_DIR, "heroes.json")
    with open(heroes_path) as f:
        heroes = json.load(f)

    out_path = os.path.join(DATA_DIR, "hero_specific_counters.json")
    with open(out_path, "w") as f:
        json.dump(HERO_COUNTERS, f, indent=2, sort_keys=True)

    total_entries = sum(len(v) for v in HERO_COUNTERS.values())
    print(f"wrote {out_path} ({len(HERO_COUNTERS)} heroes, {total_entries} entries)")
    unknown = [hid for hid in HERO_COUNTERS if hid not in heroes]
    if unknown:
        print(f"WARNING: hero ids not found in heroes.json: {unknown}")
    for hid, entries in HERO_COUNTERS.items():
        for e in entries:
            if e["vs"] not in heroes:
                print(f"WARNING: {hid} has an unknown 'vs' hero id: {e['vs']}")


if __name__ == "__main__":
    main()
